formulas.expression:
IF(ISBLANK({!Intake.Date_of_Birth__c}), 
    IF(ISBLANK({!matchedContacts.firstSelectedRow.Birthdate}), NULL, {!matchedContacts.firstSelectedRow.Birthdate}),
    IF(ISBLANK({!matchedContacts.firstSelectedRow.Birthdate}) && NOT(ISBLANK({!Intake.Date_of_Birth__c})), 
        {!Intake.Date_of_Birth__c},
        IF({!Use_data_from_which_recordBirthdate} = "Contact", 
            IF(ISBLANK({!matchedContacts.firstSelectedRow.Birthdate}), NULL, {!matchedContacts.firstSelectedRow.Birthdate}),
            IF({!Use_data_from_which_recordBirthdate} = "Intake", 
                IF(ISBLANK({!Intake.Date_of_Birth__c}), NULL, {!Intake.Date_of_Birth__c}),
                NULL
            )
        )
    )
)
